+      answer_fact_authority: 'unavailable_no_invention_allowed',
+    };
+  }
+  return {
+    posture: 'available_verified',
+    method_map_available: true,
+    procedure_model_available: true,
+    answer_fact_authority: 'verified_runtime_posture',
+  };
+}
+
+function fallbackBehavior(enabled) {
+  return {
+    enabled: enabled === true,
+    question_attempt_must_remain_available: true,
+    allowed_sources: enabled === true ? [...FALLBACK_ALLOWED_SOURCES] : [],
+    no_invention_constraints: { ...NO_INVENTION_CONSTRAINTS },
+  };
+}
+
+function eligibility({ factEligible, contextEligible = false, certaintyAllowed = false, reason }) {
+  return {
+    fact_eligible: factEligible === true,
+    context_eligible: contextEligible === true,
+    certainty_allowed: certaintyAllowed === true,
+    eligibility_reason: reason,
+  };
+}
+
+function packAssertion(assertion, rightsPosture) {
+  return {
+    assertion_id: assertionId(assertion),
+    status: assertionStatus(assertion),
+    predicate: assertion?.predicate ?? null,
+    subject_ref: assertion?.subject_ref ?? null,
+    object_ref: assertion?.object_ref ?? null,
+    scope_ref: assertion?.scope_ref ?? null,
+    confidence_band: confidenceBand(assertion),
+    risk_tier: riskTier(assertion),
+    evidence_bundle: evidenceBundleForAssertion(assertion),
+    source_spans: sourceSpansForAssertion(assertion, rightsPosture),
+  };
+}
+
+function buildPack({
+  question_id: explicitQuestionId,
+  assertion = null,
+  status,
+  semanticContext,
+  answerFactEligibility,
+  rightsPosture,
+  methodPosture,
+  downgradeInstructions = [],
+  fallbackEnabled = false,
+  includeAssertion = false,
+  excludedAssertions = [],
+}) {
+  const primaryAssertion = isObject(assertion) ? assertion : null;
+  const resolvedQuestionId = explicitQuestionId ?? questionId(primaryAssertion);
+  const resolvedAssertionId = assertionId(primaryAssertion);
+  const resolvedStatus = status ?? assertionStatus(primaryAssertion);
+  const packedAssertion = primaryAssertion ? packAssertion(primaryAssertion, rightsPosture) : null;
+  const topEvidenceBundle = packedAssertion?.evidence_bundle ?? {
+    source_families: [],
+    evidence_refs: [],
+    provenance_refs: {},
+  };
+  const topSourceSpans = packedAssertion?.source_spans ?? [];
+
+  return {
+    schema_version: PACK_SCHEMA_VERSION,
+    question_id: resolvedQuestionId,
+    assertion_id: includeAssertion ? resolvedAssertionId : null,
+    status: resolvedStatus,
+    semantic_context: semanticContext,
+    question_attempt_available: true,
+    answer_fact_eligibility: answerFactEligibility,
+    confidence_band: primaryAssertion ? confidenceBand(primaryAssertion) : 'not_applicable',
+    risk_tier: primaryAssertion ? riskTier(primaryAssertion) : 'not_applicable',
+    evidence_bundle: topEvidenceBundle,
+    source_spans: topSourceSpans,
+    rights_display_posture: rightsPosture,
+    method_procedure_posture: methodPosture,
+    downgrade_instructions: [...downgradeInstructions],
+    fallback_behavior: fallbackBehavior(fallbackEnabled),
+    assertions: includeAssertion && packedAssertion ? [packedAssertion] : [],
+    excluded_assertions: excludedAssertions,
+  };
+}
+
+function excludedAssertionFrom(assertion, override = {}) {
+  return {
+    assertion_id: assertionId(assertion),
+    status: override.status ?? assertionStatus(assertion),
+    predicate: assertion?.predicate ?? null,
+    exclusion_reason: override.exclusion_reason ?? 'excluded_status',
+    categorical_exclusion: override.categorical_exclusion === true,
+  };
+}
+
+function buildSchema({ generatedAt, paths }) {
+  return {
+    schema_version: SCHEMA_VERSION,
+    generated_at: generatedAt,
+    generated_by: SCRIPT_NAME,
+    issue: ISSUE,
+    parent_issue: PARENT_ISSUE,
+    upstream_issues: [...UPSTREAM_ISSUES],
+    subject_code: SUBJECT_CODE,
+    objective:
+      'Define EvidenceContextPack for safe RAG/Copilot consumption of accepted/provisional semantic KG.',
+    source_contract: {
+      accepted_provisional_manifest_path: paths.manifestIn,
+      rag_lite_hvy_01_validator_path: paths.ragLiteHvy01ValidatorIn,
+      accepted_delta_path: paths.acceptedDeltaIn,
+      provisional_safe_delta_path: paths.provisionalSafeDeltaIn,
+    },
+    evidence_context_pack: {
+      pack_schema_version: PACK_SCHEMA_VERSION,
+      required_fields: [...REQUIRED_PACK_FIELDS],
+      field_rules: {
+        question_id: 'Canonical question row id; nullable only for questionless sessions outside this fixture set.',
+        assertion_id:
+          'Primary semantic assertion id when an assertion is included; null when context is unavailable or excluded.',
+        status:
+          'Semantic assertion status or explicit fallback status such as semantic_kg_unavailable.',
+        confidence_band:
+          'Status-independent band from semantic KG confidence object; never creates accepted truth by itself.',
+        risk_tier: 'Risk classification preserved from semantic KG promotion inputs.',
+        evidence_bundle:
+          'Structured evidence refs, source families, and provenance refs used to support included assertions.',
+        source_spans:
+          'Artifact path and pointer spans derived from evidence refs; display follows rights/display posture.',
+        rights_display_posture:
+          'Display and answer-context permission posture; blocked display excludes answer facts.',
+        method_procedure_posture:
+          'Method Map and ProcedureModel availability posture used by Copilot fallback and repair context.',
+        downgrade_instructions:
+          'Required consumer instructions when semantic context is provisional, degraded, unavailable, or excluded.',
+      },
+    },
+    semantic_context: {
+      allowed_values: [...SEMANTIC_CONTEXT_VALUES],
+      definitions: {
+        available_verified:
+          'At least one accepted assertion is included with verified evidence, source spans, and display posture.',
+        provisional_degraded:
+          'Only provisional_safe or insufficient semantic context is available; consumers must downgrade language.',
+        unavailable:
+          'No eligible semantic KG is available; question attempt remains available through fallback sources.',
+        blocked_excluded:
+          'Available semantic content is raw, review, rejected, blocked, or rights/display-blocked and is excluded.',
+      },
+    },
+    answer_fact_eligibility: {
+      accepted: {
+        fact_eligible: true,
+        certainty_allowed: true,
+        required_semantic_context: 'available_verified',
+        required_status: 'accepted',
+        required_rights_display_posture: 'display_allowed',
+      },
+      provisional_safe: {
+        fact_eligible: false,
+        context_eligible: true,
+        certainty_allowed: false,
+        required_semantic_context: 'provisional_degraded',
+        required_downgrade_instructions: [
+          'label_as_provisional_context',
+          'do_not_render_as_certain_fact',
+          'do_not_use_for_scoring_mastery_or_rights',
+        ],
+      },
+      rights_display_blocked: {
+        fact_eligible: false,
+        context_eligible: false,
+        certainty_allowed: false,
+        required_semantic_context: 'blocked_excluded',
+      },
+    },
+    exclusion_rules: {
+      excluded_statuses: [...EXCLUDED_STATUSES],
+      raw_candidate:
+        'Candidate assertions cannot enter answer facts or default semantic context.',
+      review_required:
+        'Review-only assertions are excluded until promoted into accepted or provisional_safe.',
+      rejected:
+        'Rejected assertions are terminally excluded unless a new assertion/review cycle creates a new record.',
+      blocked_quarantined:
+        'Blocked assertions are categorically excluded regardless of confidence band or score.',
+    },
+    fallback_behavior: {
+      question_attempt_remains_available: true,
+      unavailable_semantic_context_value: 'unavailable',
+      degraded_semantic_context_value: 'provisional_degraded',
+      allowed_sources: [...FALLBACK_ALLOWED_SOURCES],
+      no_invention_constraints: { ...NO_INVENTION_CONSTRAINTS },
+    },
+    forbidden_operations: [
+      'production_rag_reindex',
+      'vector_store_mutation',
+      'remote_supabase_mutation',
+      'runtime_answer_generation',
+      'frontend_ui',
+      'external_llm_vlm_api_call',
+    ],
+  };
+}
+
+function buildFixturePacks({ acceptedAssertion, provisionalAssertion }) {
+  const acceptedRights = rightsDisplayPosture('display_allowed');
+  const provisionalRights = rightsDisplayPosture('display_allowed');
+  const blockedRights = rightsDisplayPosture('display_blocked');
+  const verifiedMethod = methodProcedurePosture('available_verified');
+  const degradedMethod = methodProcedurePosture('provisional_degraded');
+  const unavailableMethod = methodProcedurePosture('unavailable');
+  const fallbackQuestionId = questionId(acceptedAssertion, 'qrow_9709_m16_qp_12_q01');
+
+  const rawCandidateAssertion = cloneJson(provisionalAssertion);
+  rawCandidateAssertion.layer = 'raw_candidate';
+  rawCandidateAssertion.promotion_decision = 'raw_candidate';
+
+  const blockedAssertion = cloneJson(acceptedAssertion);
+  blockedAssertion.layer = 'blocked_quarantined';
+  blockedAssertion.promotion_decision = 'blocked_quarantined';
+
+  return [
+    {
+      fixture_id: 'accepted_fact',
+      description: 'Accepted semantic assertion may support an answer fact.',
+      expected_semantic_context: 'available_verified',
+      pack: buildPack({
+        assertion: acceptedAssertion,
+        semanticContext: 'available_verified',
+        answerFactEligibility: eligibility({
+          factEligible: true,
+          contextEligible: true,
+          certaintyAllowed: true,
+          reason: 'accepted_semantic_assertion_with_verified_evidence',
+        }),
+        rightsPosture: acceptedRights,
+        methodPosture: verifiedMethod,
+        includeAssertion: true,
+      }),
+    },
+    {
+      fixture_id: 'provisional_downgraded_context',
+      description: 'Provisional-safe semantic assertion is context only and cannot be rendered as certain fact.',
+      expected_semantic_context: 'provisional_degraded',
+      pack: buildPack({
+        assertion: provisionalAssertion,
+        semanticContext: 'provisional_degraded',
+        answerFactEligibility: eligibility({
+          factEligible: false,
+          contextEligible: true,
+          certaintyAllowed: false,
+          reason: 'provisional_safe_requires_visible_downgrade',
+        }),
+        rightsPosture: provisionalRights,
+        methodPosture: degradedMethod,
+        downgradeInstructions: [
+          'label_as_provisional_context',
+          'do_not_render_as_certain_fact',
+          'do_not_use_for_scoring_mastery_or_rights',
+        ],
+        includeAssertion: true,
+      }),
+    },
+    {
+      fixture_id: 'candidate_excluded',
+      description: 'Raw candidate semantic assertion is excluded from answer context.',
+      expected_semantic_context: 'blocked_excluded',
+      pack: buildPack({
+        assertion: rawCandidateAssertion,
+        status: 'raw_candidate',
+        semanticContext: 'blocked_excluded',
+        answerFactEligibility: eligibility({
+          factEligible: false,
+          contextEligible: false,
+          certaintyAllowed: false,
+          reason: 'raw_candidate_excluded',
+        }),
+        rightsPosture: provisionalRights,
+        methodPosture: degradedMethod,
+        downgradeInstructions: ['exclude_raw_candidate_assertion'],
+        excludedAssertions: [
+          excludedAssertionFrom(rawCandidateAssertion, {
+            status: 'raw_candidate',
+            exclusion_reason: 'raw_candidate_not_rag_eligible',
+          }),
+        ],
+      }),
+    },
+    {
+      fixture_id: 'blocked_excluded',
+      description: 'Blocked semantic assertion is categorically excluded regardless of confidence.',
+      expected_semantic_context: 'blocked_excluded',
+      pack: buildPack({
+        assertion: blockedAssertion,
+        status: 'blocked_quarantined',
+        semanticContext: 'blocked_excluded',
+        answerFactEligibility: eligibility({
+          factEligible: false,
+          contextEligible: false,
+          certaintyAllowed: false,
+          reason: 'blocked_quarantined_categorical_exclusion',
+        }),
+        rightsPosture: acceptedRights,
+        methodPosture: unavailableMethod,
+        downgradeInstructions: ['exclude_blocked_quarantined_assertion'],
+        excludedAssertions: [
+          excludedAssertionFrom(blockedAssertion, {
+            status: 'blocked_quarantined',
+            exclusion_reason: 'blocked_quarantined_categorical_exclusion',
+            categorical_exclusion: true,
+          }),
+        ],
+      }),
+    },
+    {
+      fixture_id: 'rights_display_blocked',
+      description: 'Rights/display blocked assertion is excluded from answer facts even if status is accepted.',
+      expected_semantic_context: 'blocked_excluded',
+      pack: buildPack({
+        assertion: acceptedAssertion,
+        status: 'rights_display_blocked',
+        semanticContext: 'blocked_excluded',
+        answerFactEligibility: eligibility({
+          factEligible: false,
+          contextEligible: false,
+          certaintyAllowed: false,
+          reason: 'rights_display_blocked',
+        }),
+        rightsPosture: blockedRights,
+        methodPosture: verifiedMethod,
+        downgradeInstructions: ['exclude_rights_display_blocked_assertion'],
+        excludedAssertions: [
+          excludedAssertionFrom(acceptedAssertion, {
+            status: 'accepted',
+            exclusion_reason: 'rights_display_blocked',
+          }),
+        ],
+      }),
+    },
+    {
+      fixture_id: 'unavailable_semantic_context',
+      description: 'Missing semantic KG does not block the question attempt.',
+      expected_semantic_context: 'unavailable',
+      pack: buildPack({
+        question_id: fallbackQuestionId,
+        status: 'semantic_kg_unavailable',
+        semanticContext: 'unavailable',
+        answerFactEligibility: eligibility({
+          factEligible: false,
+          contextEligible: false,
+          certaintyAllowed: false,
+          reason: 'semantic_kg_unavailable_fallback',
+        }),
+        rightsPosture: rightsDisplayPosture('metadata_only'),
+        methodPosture: verifiedMethod,
+        downgradeInstructions: ['fall_back_to_verified_runtime_context'],
+        fallbackEnabled: true,
+      }),
+    },
+    {
+      fixture_id: 'degraded_semantic_context',
+      description: 'Insufficient semantic KG downgrades to provisional context and fallback sources.',
+      expected_semantic_context: 'provisional_degraded',
+      pack: buildPack({
+        assertion: provisionalAssertion,
+        semanticContext: 'provisional_degraded',
+        answerFactEligibility: eligibility({
+          factEligible: false,
+          contextEligible: true,
+          certaintyAllowed: false,
+          reason: 'semantic_kg_degraded_fallback',
+        }),
+        rightsPosture: provisionalRights,
+        methodPosture: degradedMethod,
+        downgradeInstructions: [
+          'label_as_provisional_context',
+          'do_not_render_as_certain_fact',
+          'fall_back_to_verified_runtime_context',
+          'do_not_invent_concept_skill_or_procedure_facts',
+        ],
+        fallbackEnabled: true,
+        includeAssertion: true,
+      }),
+    },
+    {
+      fixture_id: 'no_invention_fallback',
+      description: 'Fallback explicitly forbids invented concept, skill, and procedure claims.',
+      expected_semantic_context: 'unavailable',
+      pack: buildPack({
+        question_id: fallbackQuestionId,
+        status: 'semantic_kg_insufficient_no_invention_fallback',
+        semanticContext: 'unavailable',
+        answerFactEligibility: eligibility({
+          factEligible: false,
+          contextEligible: false,
+          certaintyAllowed: false,
+          reason: 'no_verified_semantic_claim_source',
+        }),
+        rightsPosture: rightsDisplayPosture('metadata_only'),
+        methodPosture: unavailableMethod,
+        downgradeInstructions: ['do_not_invent_concept_skill_or_procedure_facts'],
+        fallbackEnabled: true,
+      }),
+    },
+  ];
+}
+
+function requiredFieldsPresent(pack) {
+  return REQUIRED_PACK_FIELDS.filter((field) => !(field in pack));
+}
+
+function packHasValidEvidence(pack) {
+  if (!Array.isArray(pack.assertions) || pack.assertions.length === 0) return true;
+  return pack.assertions.every((assertion) => (
+    isObject(assertion.evidence_bundle) &&
+    Array.isArray(assertion.evidence_bundle.evidence_refs) &&
+    assertion.evidence_bundle.evidence_refs.length > 0 &&
+    Array.isArray(assertion.source_spans) &&
+    assertion.source_spans.length > 0 &&
+    assertion.source_spans.every((span) => hasString(span.artifact_path) && hasString(span.pointer))
+  ));
+}
+
+function fixtureValidationErrors({ schema, fixture }) {
+  const errors = [];
+  const pack = fixture?.pack;
+  if (!isObject(pack)) return [`${fixture?.fixture_id ?? 'unknown'}:pack_missing`];
+
+  const missingFields = requiredFieldsPresent(pack);
+  errors.push(...missingFields.map((field) => `${fixture.fixture_id}:pack_field_missing:${field}`));
+
+  if (!schema?.semantic_context?.allowed_values?.includes(pack.semantic_context)) {
+    errors.push(`${fixture.fixture_id}:invalid_semantic_context:${pack.semantic_context}`);
+  }
+
+  if (fixture.expected_semantic_context && pack.semantic_context !== fixture.expected_semantic_context) {
+    errors.push(`${fixture.fixture_id}:unexpected_semantic_context:${pack.semantic_context}`);
+  }
+
+  if (pack.semantic_context === 'available_verified') {
+    const acceptedAssertion = pack.assertions?.[0];
+    if (acceptedAssertion?.status !== 'accepted') {
+      errors.push(`${fixture.fixture_id}:accepted_fact_missing_accepted_assertion`);
+    }
+    if (pack.answer_fact_eligibility?.fact_eligible !== true ||
+      pack.answer_fact_eligibility?.certainty_allowed !== true) {
+      errors.push(`${fixture.fixture_id}:accepted_fact_not_answer_fact_eligible`);
+    }
+  }
+
+  if (pack.semantic_context === 'provisional_degraded') {
+    if (pack.answer_fact_eligibility?.fact_eligible === true ||
+      pack.answer_fact_eligibility?.certainty_allowed === true) {
+      errors.push(`${fixture.fixture_id}:provisional_context_rendered_as_certain_fact`);
+    }
+    const needsDowngrade = pack.assertions?.some((assertion) => assertion.status === 'provisional_safe') ||
+      fixture.fixture_id === 'degraded_semantic_context';
+    if (needsDowngrade && !pack.downgrade_instructions?.includes('do_not_render_as_certain_fact')) {
+      errors.push(`${fixture.fixture_id}:provisional_context_missing_downgrade_instruction`);
+    }
+  }
+
+  const excludedUnsafe = pack.excluded_assertions?.some((assertion) => (
+    EXCLUDED_STATUSES.includes(assertion.status)
+  ));
+  if (excludedUnsafe) {
+    if (pack.assertions.length !== 0) errors.push(`${fixture.fixture_id}:unsafe_status_not_excluded`);
+    if (pack.semantic_context !== 'blocked_excluded') {
+      errors.push(`${fixture.fixture_id}:unsafe_status_wrong_semantic_context`);
+    }
+    if (pack.answer_fact_eligibility?.fact_eligible !== false ||
+      pack.answer_fact_eligibility?.certainty_allowed !== false) {
+      errors.push(`${fixture.fixture_id}:unsafe_status_answer_fact_allowed`);
+    }
+  }
+
+  const rightsBlocked = pack.rights_display_posture?.posture === 'display_blocked';
+  if (rightsBlocked) {
+    if (pack.assertions.length !== 0) errors.push(`${fixture.fixture_id}:rights_display_blocked_not_excluded`);
+    if (pack.answer_fact_eligibility?.fact_eligible !== false ||
+      pack.answer_fact_eligibility?.certainty_allowed !== false) {
+      errors.push(`${fixture.fixture_id}:rights_display_blocked_answer_fact_allowed`);
+    }
+    if (!pack.excluded_assertions?.some((assertion) => (
+      assertion.exclusion_reason === 'rights_display_blocked'
+    ))) {
+      errors.push(`${fixture.fixture_id}:rights_display_blocked_missing_exclusion_reason`);
+    }
+  }
+
+  if (pack.fallback_behavior?.enabled === true) {
+    if (pack.question_attempt_available !== true) {
+      errors.push(`${fixture.fixture_id}:fallback_attempt_unavailable`);
+    }
+    if (JSON.stringify(pack.fallback_behavior.allowed_sources) !==
+      JSON.stringify(FALLBACK_ALLOWED_SOURCES)) {
+      errors.push(`${fixture.fixture_id}:fallback_allowed_sources_invalid`);
+    }
+    if (JSON.stringify(pack.fallback_behavior.no_invention_constraints) !==
+      JSON.stringify(NO_INVENTION_CONSTRAINTS)) {
+      errors.push(`${fixture.fixture_id}:fallback_allows_invented_semantic_claims`);
+    }
+  }
+
+  if (!packHasValidEvidence(pack)) {
+    errors.push(`${fixture.fixture_id}:included_assertion_missing_evidence_or_source_spans`);
+  }
+
+  return errors;
+}
+
+export function validateEvidenceContextPackFixtures({ schema, fixtures }) {
+  const fixtureResults = Array.isArray(fixtures?.fixture_results)
+    ? fixtures.fixture_results
+    : [];
+  const errors = [];
+  const evaluatedFixtures = fixtureResults.map((fixture) => {
+    const fixtureErrors = fixtureValidationErrors({ schema, fixture });
+    errors.push(...fixtureErrors);
+    return {
+      ...fixture,
+      pass: fixtureErrors.length === 0,
+      errors: fixtureErrors,
+    };
+  });
+  return {
+    status: errors.length === 0 ? 'pass' : 'fail',
+    errors,
+    fixture_results: evaluatedFixtures,
+  };
+}
+
+function sourceArtifactRef(root, relPath, role) {
+  return {
+    role,
+    path: relPath,
+    exists: Boolean(resolvePath(root, relPath) && fs.existsSync(resolvePath(root, relPath))),
+    sha256: sha256File(root, relPath),
+  };
+}
+
+function validatorStatus(validator) {
+  return validator?.validator_status ?? validator?.summary?.validation_status ?? 'unknown';
+}
+
+function check(id, condition, evidence = {}) {
+  return {
+    id,
+    status: condition ? 'pass' : 'fail',
+    evidence,
+  };
+}
+
+function renderTable(headers, rows) {
+  return [
+    `| ${headers.join(' | ')} |`,
+    `| ${headers.map(() => '---').join(' | ')} |`,
+    ...rows.map((row) => `| ${row.join(' | ')} |`),
+  ].join('\n');
+}
+
+function renderReadback(result) {
+  const { summary, checks, errors } = result.validatorResult;
+  const fixtureRows = result.fixtures.fixture_results.map((fixture) => [
+    fixture.fixture_id,
+    fixture.pack.semantic_context,
+    String(fixture.pack.answer_fact_eligibility.fact_eligible),
+    String(fixture.pack.downgrade_instructions.length > 0),
+    fixture.pass ? 'pass' : 'fail',
+  ]);
+
+  return `# RAG-LITE-HVY-02 EvidenceContextPack Schema Readback
+
+Issue: #${ISSUE}
+Parent: #${PARENT_ISSUE}
+Upstream issues: #${UPSTREAM_ISSUES.join(', #')}
+Validation status: \`${result.validatorResult.validator_status}\`
+
+## Scope
+
+- Defined \`EvidenceContextPack\` schema for accepted, provisional, unavailable, degraded, and excluded semantic KG.
+- Preserved answer-fact eligibility separation: accepted may be fact-eligible; provisional_safe is downgraded context only.
+- Excluded raw_candidate, review_required, rejected, blocked_quarantined, and rights/display-blocked assertions from answer facts.
+- Defined fallback behavior where question attempts remain available and Copilot/RAG falls back to question text, runtime evidence, Method/Procedure posture, and other verified evidence.
+- No production RAG reindex, vector-store mutation, remote Supabase mutation, runtime answer generation, frontend work, or external LLM/VLM/API call occurred.
+
+## Summary
+
+| Metric | Value |
+| --- | ---: |
+| Fixture count | ${summary.fixture_count} |
+| Fixture pass count | ${summary.fixture_pass_count} |
+| Fixture fail count | ${summary.fixture_fail_count} |
+| Semantic context value count | ${summary.semantic_context_value_count} |
+| Fallback fixture count | ${summary.fallback_fixture_count} |
+| Excluded fixture count | ${summary.excluded_fixture_count} |
+
+## Semantic Context Values
+
+${SEMANTIC_CONTEXT_VALUES.map((value) => `- \`${value}\``).join('\n')}
+
+## Fixture Results
+
+${renderTable(
+  ['Fixture', 'Semantic context', 'Fact eligible', 'Downgrade required', 'Status'],
+  fixtureRows,
+)}
+
+## Validator Checks
+
+${renderTable(['Check', 'Status'], checks.map((item) => [item.id, item.status]))}
+
+## Errors
+
+${errors.length > 0 ? errors.map((item) => `- ${item}`).join('\n') : '- None'}
